INSERT INTO patients (id, global_user_id, phone, emergency_phone, address, age_range, relationship_status, occupation_type, living_situation, primary_goal, has_previous_therapy) VALUES (2, 'u_pat4', '+9999999999', '+9999999990', 'Urbanización Los Pinos, Apto 4', '45-55', 'Divorciada', 'Gerente de Ventas', 'Vive sola', 'Duelo por separación dolorosa reciente', TRUE);
INSERT INTO treatments (id, patient_id, state) VALUES (1, 1, 'ACTIVE');
INSERT INTO treatments (id, patient_id, state) VALUES (2, 2, 'ACTIVE');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-15', 'audio', 'Día 1: Hoy fue uno de esos días en los que todo parece salir mal. Empezó con un examen que, bueno, no me fue tan bien como esperaba. Me sentí, no sé, como si estuviera en una montaña rusa emocional. Antes del examen, tenía un nudo en el estómago, supongo que era la ansiedad. Durante la prueba, mis ideas se escabullían, olvidé conceptos que había estudiado. Es frustrante, porque he puesto tanto esfuerzo. Cuando salió el resultado, me di cuenta de que no había pasado. Me sentí derrotado, como si la tierra se me hubiera caído encima. No sé, me invadió un miedo profundo. Después del examen, intenté hablar con mis compañeros, pero no sabía cómo expresar lo que sentía. Al final, me encerré en mi cuarto y traté de estudiar de nuevo. Siento que nunca es suficiente. Este ciclo de querer ser perfecto es cansado y no sé si lo lograré. Estoy comenzando a cuestionar si elegí la carrera correcta. Desde entonces, he estado más tenso y con un peso en el pecho que no se va.', 'Luis, siento que hoy fue un día realmente difícil para ti, y es normal sentirte abrumado después de un examen tan impactante. Es comprensible que la ansiedad y el miedo al fracaso se intensifiquen en momentos así. Recuerda que el resultado de un examen no define tu capacidad o tu valor como estudiante y como persona. Nos lleva tiempo procesar estas emociones, pero lo importante es que puedas ser amable contigo mismo y reconocer el esfuerzo que has puesto en tu camino.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-17', 'audio', 'Día 2: Hoy decidí que sería un día diferente, pero, eh, me costó. La verdad es que el recuerdo del examen de ayer todavía pesa mucho sobre mí. Intenté salir con mis compañeros a comer, pero no podía quitarme la sensación de fracaso. En la comida, traté de reírme y de disfrutar, pero, constantemente, mi mente regresaba a esos resultados. Regresando, me encontré con un grupo de compañeros que hablaban sobre sus próximos exámenes y, aunque intenté integrarme, me sentí como un impostor. La ansiedad regresó y, aunque no me gusta mostrarlo, creo que es evidente en mi cara. Empecé a dudar de mis decisiones: ¿será que no estoy a la altura? Intenté estudiar, pero solo lograba distraerme. En este punto, me está costando un poco dividir mi tiempo entre estudiar y cuidar de mi salud mental. Me siento un poco atascado.', 'Luis, es natural que te sientas atascado después de un día tan intenso como el de ayer. Intentar cambiar tu estado de ánimo y salir con amigos es un paso valiente. Es admirable que estés buscando momentos de conexión, incluso cuando te sientes así. Los pensamientos de impostor pueden ser muy pesados, y es vital que reconozcas que todos enfrentamos estos momentos de duda. Permítete aceptar tus sentimientos y saber que es un proceso. Estás en un camino lleno de aprendizajes, y cada día cuenta.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-18', 'audio', 'Día 3: Este día empezó un poco mejor, debo admitir. He estado tratando de practicar la meditación, aunque, eh, me parece un tanto difícil en este momento. Me propuse establecer un horario de estudio. A la mañana, sentí una pequeña victoria al sentarme y repasar algunos conceptos. Pero luego, a media tarde, recibí un mensaje de un grupo donde alguien comentaba que ya había terminado la lectura de un tema que yo había pospuesto. De nuevo, eso me arrastró a la espiral del miedo al fracaso. Inclusive comenzaron esos pensamientos de ''no soy lo suficientemente bueno''. Después de ese momento, decidí dar un paseo al aire libre para despejar mi mente. Me hizo bien, pero todavía tengo miedo de la próxima evaluación. Estoy atrapado entre querer seguir adelante y el temor de fallar nuevamente.', 'Luis, es genial que hayas encontrado un momento de claridad al establecer un horario de estudio y que quieras explorar la meditación. Permítete disfrutar de esos pequeños pasos, aunque parezcan insignificantes. Es completamente normal que los logros de los demás puedan activar esos pensamientos de duda, pero trata de recordar que cada quien tiene su propio ritmo y proceso. Tomar un tiempo para ti mismo y salir a caminar fue una decisión saludable. Cada día es una oportunidad para aprender y crecer, y lo estás haciendo muy bien al ser consciente de lo que sientes.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-19', 'audio', 'Día 4: La noche pasada no pude dormir bien. Pasé horas dando vueltas, reponiéndome sobre lo que ocurrió en los últimos exámenes. Esta mañana, incluso tomé café de más para intentar activarme. En las clases, en realidad no pude concentrarme del todo. La profesora comenzó a hablar de un tema que no entendía, y sentí que me atrapaba el pánico. Este sentimiento de angustia fue aumentando y, a la hora de la comida, simplemente estuve en silencio. Mis compañeros notaron que algo no estaba bien. Intentaron hablarme, pero no encontraba el valor para abrirme sobre cómo me siento. Me siento un poco solo en esto, como si nadie pudiera entender la presión que siento. La ansiedad vuelve y siento que no tengo control sobre ella. Incluso me costó hablar con mi profe después de clase sobre mis dudas.', 'Luis, lamento que hayas tenido otra noche difícil. La falta de sueño puede afectar mucho cómo nos sentimos durante el día. Es comprensible que la ansiedad te haya invadido en clase, especialmente con temas que no son claros para ti. Es un paso valiente reconocer que tus compañeros se preocuparon por ti. No estás solo en esto, y hay personas que se preocupan por ti, aunque abrirse puede ser complicado. Recordar que buscar ayuda, ya sea de compañeros o profesores, no significa debilidad, puede ser un acto de fortaleza. Tómate tu tiempo y sigue avanzando.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-20', 'audio', 'Día 5: Hoy fue un poco más leve. Decidí que, a pesar del torbellino emocional de los días anteriores, tenía que ir a clase. La profesora mencionó que había un programa de tutores y, eh, esta vez, me animé a inscribirme. No sé si esto solucionará mis problemas, pero creo que es un paso. Durante la clase, logré hacer algunas preguntas, aunque sigue siendo incómodo. Después de clases, me quedé un rato hablando con un tutor y eso me hizo sentir algo mejor. No sé, al menos hay alguien que puede ayudarme a clarificar. Pero siento que estoy en un tira y afloja permanente entre el querer y el miedo. A veces creo que tomaría decisiones más fáciles si no tuviera este peso del miedo al fracaso. Pero, hoy un rayito de esperanza brilla un poco más.', 'Luis, me alegra saber que hoy has dado ese importante paso al inscribirte en el programa de tutores. Buscar apoyo es un gran signo de fuerza y autoconocimiento, y no todos tienen la valentía de hacerlo. También es positivo ver que lograste hacer preguntas en clase; eso muestra que estás comprometido con tu aprendizaje. Es perfectamente natural sentir esa tensión entre el deseo de avanzar y el miedo. Aceptar que sentir miedo es parte del proceso es parte clave de seguir adelante. Celebra cada pequeño logro, porque son pasos que te acercan a tus metas.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-21', 'audio', 'Día 6: Hoy fue un caos total. Al despertarme, me di cuenta de que había olvidado un compromiso importante: un estudio grupal con mis compañeros. Cuando llegué, todos ya habían revisado casi todo y me sentí completamente perdido. Durante el estudio, me costó seguirles el ritmo. Sentí que las palpitaciones en mi pecho regresaban, y no sé, eso me frustra. Ya sé que he de trabajar en mi gestión del tiempo, pero todo a la vez se siente abrumante. Al final de la noche, no pude evitar un ataque de ansiedad. Mi compañero tuvo que hablarme y tranquilizarme un poco, lo que fue bueno, pero también me siento avergonzado. No puedo seguir así y, a pesar de lo que intento, siento que estoy fallando. Algunas veces me pregunto si esto es lo que me espera siempre. No sé cómo seguir adelante.', 'Luis, lo que viviste hoy es muy válido y, aunque sientas que fue caótico, el simple hecho de haber intentado participar en el estudio grupal es un esfuerzo digno de reconocer. La ansiedad puede ser muy abrumadora y puede aparecer en momentos inesperados, y no tienes por qué avergonzarte de pedir ayuda a tus compañeros. Apenas estás empezando a construir tus habilidades para manejar estas situaciones. Permítete sentir lo que sientes sin juzgarte, y recuerda que tienes tiempo para aprender y crecer. La jornada de cada día es una oportunidad para avanzar un poco más.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-22', 'text', 'Día 7: Hoy sentí que tenía que parar un poco y reflexionar. Pasé la mañana en la biblioteca, nuevamente con el tutor. Comencé a sentirme un poco más seguro, como si realmente me estuvieran ayudando a ver las cosas de manera diferente. El asesoramiento me abrió los ojos. Tenía tanto miedo de quedarme atrás, que no me di cuenta de que ya tenía herramientas. Fue un momento de revelación, podría decir. Las palpitaciones disminuyeron un poco, y empecé a avanzar en mis estudios. En la tarde, decidí darme un pequeño lujo, compré una nueva novela de ficción. Me había olvidado de la lectura por placer y eso me hizo sentir un poco más ligero. Siento que estoy empezando a recuperar la esperanza. Siendo sincero, el miedo aún está ahí, pero estoy comenzando a construir una mejor relación con mis emociones.', 'Eso suena maravilloso, Luis. Es realmente inspirador escuchar que has tenido una revelación positiva al trabajar con tu tutor. Tomarte un tiempo para reflexionar y ser amable contigo mismo es esencial, tanto en los estudios como en el manejo de tus emociones. Volver a sumergirte en una lectura por placer es un excelente modo de cuidar tu bienestar emocional y recordar que la vida está hecha de momentos de conexión. Tienes el derecho de disfrutar esos pequeños placeres. Sigue avanzando como lo estás haciendo; estás en un camino de crecimiento y descubrimiento.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-23', 'text', 'Día 8: Hoy fue un poco diferente, supongo. Asistí a una charla de bienestar organizada por la universidad, lo que fue bastante útil. Hablaban sobre cómo manejar el estrés y algunos tips para mantener la salud mental. La verdad es que me sentí un poco inspirado. Sin embargo, también me dio miedo darme cuenta de que todavía tengo mucho que trabajar. Cuando llegué a casa, me sentía un poco ansioso, pero lo intenté. Asistí a la reunión que tenía programada con el tutor, y eso me ayudó. Hablamos de planes a largo plazo y eso me dio cierto alivio. Sigo teniendo días difíciles, pero voy aprendiendo a gestionarlos. Aunque a veces soy duro conmigo mismo, empiezo a reconocer que estoy haciendo lo mejor que puedo en este momento. Al final del día, es un proceso, ¿no? Así que estaré aquí, intentando cada día.', 'Luis, me alegra saber que asististe a la charla de bienestar; es un enorme paso el que estés buscando activamente estrategias para manejar el estrés. Reconocer que hay cosas en las que trabajar no significa que estés haciendo algo mal, sino que estás aprendiendo y creciendo. La conversación con tu tutor sobre planes a largo plazo es una excelente forma de visualizar un futuro más equilibrado. Recuerda ser compasivo contigo mismo. El proceso es fundamental, y estar presente en cada paso que das es lo más importante en este viaje.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-25', 'text', 'Día 9: Hoy, la carga de tareas volvió a golpearme. Honestamente, me sentí un poco abrumado nuevamente, especialmente al ver que algunos compañeros parecían pasarla mejor. Me dejé llevar por el desánimo en la biblioteca, y las distracciones eran demasiadas. A veces, me cuestiono si debería cambiar mi enfoque y quizás dejar la medicina. Es un miedo constante que ronda mi mente. Pero luego, me acordé de los consejos que me dieron en la charla y traté de hacer una lista de prioridades. Al final, aunque no logré hacer todo lo que quería, logré completar algunas tareas. No sé si eso debería ser suficiente, pero por ahora, es lo que tengo. Este camino no ha sido sencillo, pero estoy comenzando a adaptarme.', 'Luis, es completamente natural sentirte abrumado cuando las tareas parecen acumularse y compararte con tus compañeros puede disparar esos sentimientos de inseguridad. Lo importante es que has comenzado a desarrollar métodos para manejar esos momentos difíciles, como hacer una lista de prioridades. Esa es una herramienta útil que te ayudará a sentirte más en control. Cada pequeño logro cuenta, y trabajar en tus tareas a tu ritmo es válido. Este trayecto no es sencillo, pero sigue siendo un viaje hacia el crecimiento personal y académico.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (1, '2026-06-29', 'audio', 'Día 10: Hoy decidí darme un día libre de toda la presión. No sé, lo sentí necesario. Fui al cine con unos amigos y me olvidé de las preocupaciones, al menos por un par de horas. La película me hizo reír y ese respiro me ayudó a recargar energías. Al volver, con un poco más de claridad, pensé en lo que voy a hacer para manejar mejor las crisis en el futuro. Tal vez, una mezcla de estudiar y no descuidar mis momentos de ocio. Sigo con la mente alerta al miedo de fallar, pero creo que últimamente estoy aprendiendo a vivir con eso. Quiero seguir adelante, pero no sé si en este punto me siento totalmente listo. Sin embargo, creo que el simple hecho de permitirme un descanso fue un paso adelante. Estoy empezando a entender que cuidarme a mí mismo es parte del proceso.', 'Luis, decidir darte un día libre es muy autoconsciente y saludable. Es fundamental reconocer la importancia de desconectarte y reponer energías. Ir al cine y disfrutar de unas risas son formas excelentes de cuidar tu salud emocional. La reflexión sobre cómo equilibrar el estudio y el ocio es también un paso importante; no puedes rendir al máximo si no te das tiempo para ti mismo. Aceptar que el miedo al fracaso está presente, pero encontrar maneras de convivir con él, te permite avanzar. Sigue buscando esos momentos de equilibrio, porque son esenciales en tu camino.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-16', 'audio', 'Día 1: Hoy fue un día realmente difícil. Me desperté sintiéndome muy abrumada por la tristeza. Honestamente, el solo hecho de levantarme de la cama me costó un montón. Me miré al espejo y no reconocí a la persona que estaba viendo. Los recuerdos de nuestra última discusión volvieron a mi mente, y terminé llorando. El trabajo fue un caos, recibí un par de quejas de clientes que, normalmente, podría manejar sin problema, pero hoy me sentía más irritable que nunca. No sé si mi equipo lo notó, aunque hice un esfuerzo por actuar normal. Regresando a casa, el silencio fue ensordecedor. Me senté en el sofá, rodeada de la misma soledad que he estado intentando evitar. La noche fue bastante larga y las horas parecían eternas.', 'Sofía, lamento saber que hoy ha sido tan pesado para ti. Es completamente normal sentirte abrumada por momentos como estos, especialmente cuando estás lidiando con el dolor de una separación. Permítete sentir esas emociones; son una parte importante del proceso de duelo. Recuerda que no estás sola en esto, y tomarte un tiempo para ti misma es fundamental. Tu valentía al enfrentar estos sentimientos es un paso hacia la sanación.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-17', 'audio', 'Día 2: Me he dado cuenta de que el dolor de ayer no se ha ido, pero hoy fue un poco diferente. Ha sido un día con altibajos. Por la mañana decidí salir a caminar; sentí que necesitaba un cambio de ambiente. Mientras caminaba, vi una pareja de ancianos tomados de la mano y eso me hizo sentir aún más triste. Me costó concentrarme en el trabajo de nuevo; me sentía fuera de lugar. Mi compañera de trabajo me preguntó cómo estaba, y por un instante, pensé en abrirme, pero no lo hice. En lugar de eso, sonreí y dije que estaba bien. Al final del día, antes de volver a casa, compré una flor. Aunque sea un pequeño gesto, me hace sentir un poco más viva.', 'Es un gran paso que hayas salido a caminar, Sofía. Es natural que los recuerdos de las parejas te afecten, sobre todo en este momento de tu vida. La tristeza es una parte del duelo, y es valiente de tu parte reconocer cómo te sientes. También es completamente normal no querer abrirte en cada ocasión; la toma de decisiones sobre cuándo compartir tus emociones lleva tiempo. Ese gesto de comprarte una flor es muy significativo; cuídate a ti misma de formas pequeñas, pero importantes. Estás haciendo un trabajo valioso en tu proceso de sanación.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-20', 'audio', 'Día 3: Hoy me encontré pensando en momentos felices, lo que supuso una pequeña victoria pero también me llevó a una tristeza profunda. Recordé nuestra primera cita y cómo me hacía sentir. El día en el trabajo fue nuevamente en piloto automático. No sé, me costó hacer conexiones con mis compañeros, como si estuvieran en otro mundo. Sentí que todos estaban respirando normal, mientras yo me ahogaba por dentro. En la tarde, tuve una llamada de un cliente que, por supuesto, no quería recibir. Su descontento me afectó de forma desproporcionada. Regresé a casa agotada y solo quería hundirme en el sofá. Pero, en un momento de debilidad, llamé a una amiga. Conversar me ayudó a sentirme menos sola.', 'Sofía, es comprensible que al recordar momentos felices sientas una mezcla tan intensa de emociones. Esa dualidad de la felicidad y la tristeza es parte de la experiencia del duelo. Es un gran paso que hayas decidido llamar a tu amiga; a veces, compartir nuestras cargas puede ser muy liberador. El dolor que sientes es válido, así que no te presiones por sentir que debes estar ''bien''. Cada día es una oportunidad para procesar tu duelo de una manera que funcione para ti.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-21', 'audio', 'Día 4: Hoy me desperté sintiéndome rara... como si hubiera un peso en mi pecho. Intenté meditar por unos minutos, pero fue difícil. Siento que estoy en una montaña rusa emocional; hay momentos en que me siento fuerte y otros en los que simplemente quiero rendirme. La reunión de ventas fue un desastre; mis ideas no fluían y mis compañeros estaban inquietos. Me sentí fuera de lugar, como si no perteneciera a ese entorno. Además, hay una presión extra porque tengo que liderar, pero a veces solo deseo poder desaparecer. Al regresar del trabajo, me senté a cenar sola y me di cuenta de lo mucho que extraño la compañía. Terminé llamando a mi hermana, pero aun así, siento un vacío. No estoy segura de qué hacer con todas estas sensaciones.', 'Sofía, lo que describes es muy normal en el proceso de duelo. Es natural sentir que tus emociones son inconsistentes y fluctuantes. La presión que sientes en el trabajo no hace más que agravar tus sentimientos de soledad. Es desafiante estar en un rol de liderazgo cuando estás lidiando con tu propio dolor. Te animo a que te permitas esos momentos de vulnerabilidad y sigas buscando apoyo en personas cercanas, como tu hermana. No tienes que atravesarlo sola; está bien cuidarte y reconocer tus propios límites.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-22', 'audio', 'Día 5: Hoy fue un día un poco mejor, supongo. La noche de ayer hablando con mi hermana me hizo sentir un poco más apoyada. En el trabajo, decidí dejar de luchar contra la corriente. Aprendí a delegar algunas tareas a mi equipo y, curiosamente, eso alivió algo de la tensión. Recibí un par de elogios sobre cómo manejé una situación con un cliente, lo que me hizo sentir bien aunque fuera por un momento. Sin embargo, esta tarde, mientras hacía la compra, vi a una pareja que se reía y eso me abrumó de nuevo. Peticiones inesperadas de mi ex terminaron el día de mala manera. Regresé a casa con la cabeza llena. Estoy tratando de encontrar un equilibrio entre mis logros y mis emociones.', 'Qué bueno que encontraste un poco de alivio hoy al delegar tareas y que tus logros en el trabajo te hicieron sentir bien. Es normal que aun así te sobrecojan momentos como el que describiste al ver a la pareja. El duelo no sigue un patrón lineal, y es totalmente válido que sientas altibajos. Permítete esos momentos de conexión y desconexión en tu vida. Mantener un equilibrio es un proceso, y lo estás haciendo extraordinariamente bien al identificar tus emociones y buscar maneras de manejarlas.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-23', 'text', 'Día 6: Hoy fue uno de esos días en que todo parece ceder. Tal vez sea el resultado de la charla con mi hermana o simplemente que estoy tocando fondo, pero me desperté sintiendo como si el mundo estuviera en una neblina. En el trabajo, traté de ser proactiva, pero sentí que iba a un ritmo más lento de lo habitual. Cansada de tratar de esconder mis emociones, decidí hablar con un miembro de mi equipo que notó mi falta de energía. Abrí el corazón un poco; no creo que lo entendiera completamente, pero fue una liberación. Al volver a casa, me senté a escribir en mi diario. Cosas simples, como listar mis emociones. Me sentí un poco más ligera al hacerlo.', 'Sofía, es inspirador que te hayas permitido abrirte a tu compañero de trabajo, eso es un gran paso hacia la recuperación. Los días en que sientes que las cosas ''ceden'' pueden ser difíciles, pero también son oportunidades para soltar parte de esa carga emocional. Es excelente que estés utilizando tu diario como un espacio seguro para expresar tus emociones; escribir puede ser una herramienta poderosa en este proceso. Estás haciendo un trabajo significativo al enfrentarte a tus sentimientos y buscar honestidad en tu experiencia.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-25', 'audio', 'Día 7: Parece que este viaje es más complicado de lo que pensaba. Hoy, la neblina que había sentido se ha disipado un poco, pero eso no significa que esté bien del todo. Durante el desayuno, vi fotos de mi ex en redes sociales y simplemente me detuve a verlas. Una parte de mí quería dejar de seguirlo, pero otra parte no puede evitarlo. El trabajo fue más productivo y logré terminar varios proyectos. Sin embargo, al final del día, me sentí un poco vacía al llegar a casa. Gente me decía que debería salir a conocer a alguien, pero eso no se siente bien. Estoy contenta de tener momentos productivos, pero por dentro sigo lidiando con una sensación de pérdida.', 'Es completamente natural que los recuerdos y las redes sociales traigan una mezcla de emociones intensas; es una parte del duelo hacia la que debes ser paciente contigo misma. Es un gran logro que hayas tenido un día productivo en el trabajo, eso es algo que deberías celebrar. La espera de que las cosas puedan ''mejorar’ a veces genera presión, pero está bien no sentirte lista para salir o conocer a alguien nuevo. El proceso de duelo no tiene un tiempo definido, y es fundamental que te des ese espacio. Sigue avanzando a tu propio ritmo.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-26', 'audio', 'Día 8: Hoy me desperté sintiendo un ligero rayo de esperanza. Fue extraño, pero me hizo sonreír al darme cuenta de que las cosas positivas también pueden ocurrir. Mientras me preparaba para ir a trabajar, decidí ponerme algo que me hiciera sentir bien; elegí un vestido que me gusta. En el trabajo, recibí un cumplido de un cliente sobre cómo manejé una situación compleja. Eso me hizo sentir segura. La jornada pasó volando, y al final del día, incluso fui a cenar con un grupo de amigos. La conversación fluyó y, aunque hubo momentos de nostalgia, me sentí un poco renovada. Al llegar a casa, escribí sobre mis pequeñas victorias. No sé, tal vez esto signifique que estoy haciendo progresos.', 'Qué hermoso escuchar que experimentaste un destello de esperanza hoy, Sofía. Esas pequeñas decisiones, como vestirte para sentirte bien, tienen un gran impacto en cómo percibes el mundo. Tus logros en el trabajo son motivo de celebración, y salir a cenar con amigos es un paso importante hacia la conexión y el apoyo que necesitas. Aunque aún puedas sentir nostalgia, es un signo de tu fortaleza el poder disfrutar de momentos agradables. Sigue disfrutando de esas pequeñas victorias; son testimonio de tu resiliencia y de tu capacidad para sanar.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-27', 'text', 'Día 9: Hoy me sentí un poco irritada. Tal vez sea porque me siento vulnerable. Sentí como si el mundo estuviera encima de mí. En el trabajo, no podía soportar la idea de que algunos compañeros se reían y platicaban como si no hubiera un peso sobre mí. Me costó concentrarme y fui más breve en las conversaciones. En la tarde, no pude evitar sentir enojo hacia mí misma por no poder ''superar'' esto más rápido. Al llegar a casa, busqué una serie en streaming que me distrajera. Me sentía cansada, aun así, hice un esfuerzo por salir a caminar. Necesitaba aire fresco; a veces siento que me ahogaré de tanto pensar. La caminata fue agridulce; dejé salir algunas lágrimas. ', 'Sofía, es completamente comprensible que te sientas irritable y vulnerable hoy. Los altibajos son parte del duelo, y tener días difíciles no significa que estás retrocediendo en tu proceso. Es normal que las risas y la alegría de los demás te resulten abrumadoras en días así. Permítete sentir esa frustración y enojo; son parte natural de la experiencia. La caminata te dio un espacio para liberar esas emociones, y eso es valioso. Continúa buscando formas de cuidarte y no te juzgues por cómo te sientes; cada uno tiene su propio viaje en este proceso.', 'completed');
INSERT INTO journalings (treatment_id, date, entry_type, transcription, ai_reply_text, status) VALUES (2, '2026-06-28', 'text', 'Día 10: Hoy me desperté sintiéndome más ligera. Quizás la caminata de ayer ayudó a despejar mi mente. Durante la mañana, decidí revisar mis metas y lo que me gustaría lograr en el futuro, no solo en el trabajo, sino también en mi vida personal. Estuve escribiendo y visualizando lo que quiero. En el trabajo, volví a sentirme como yo misma y hasta di un par de ideas frescas en una reunión. Al salir, me di cuenta de que los días oscuros continúan, pero no son los únicos días. Regresé a casa sintiendo una mezcla de gratitud y nostalgia. Todavía hay dolor por lo que he perdido, pero a la vez, creo que estoy comenzando a ver algunas luces al final del túnel.', 'Es maravilloso saber que hoy te sientes más ligera, Sofía. El hecho de que hayas dedicado tiempo a revisar tus metas es un gran indicador de tu deseo de avanzar. Esos momentos de autoconciencia y de conexión contigo misma son pasos importantes en el proceso de duelo. Aceptar que los días oscuros pueden coexistir con momentos de gratitud y esperanza es una parte esencial del viaje. Estás mostrando una resiliencia increíble y te animo a seguir este camino de autoreflexión y crecimiento que te está llevando hacia la sanación.', 'completed');
